// Tool definitions + executors for the schedule assistant.
//
// Definitions: all strict:true, input_schema with additionalProperties:false
// and explicit required arrays (claude-api strict-tool reference). Executors
// take (sb, scheduleCtx, input), zod-validate write inputs, and reuse the
// EXISTING modules (replaceActivePattern, sequence auto-fill via mutations,
// autoGenerate/autoGenerateDayShifts, patternWarnings) — nothing structural
// is re-implemented here.
import { z } from 'zod';
import { CallPatternDocSchema, patternWarnings } from '@/lib/rulesEngine/callPattern';
import {
  ShiftTypeUpsertSchema,
  ShiftTypePatchSchema,
  RuleDefinitionUpsertSchema,
} from '@/lib/validation/scheduling';
import { autoGenerate as realAutoGenerate } from '@/lib/rulesEngine/autoGenerate';
import { autoGenerateDayShifts as realAutoGenerateDayShifts } from '@/lib/rulesEngine/dayShiftAutoGen';
import { trimUnfilled, MAX_CANDIDATE_REASONS } from '@/lib/rulesEngine/trimUnfilled';
import { addDays, datesOverlap, dayTypeBucket, isBlockingAvailability } from '@/lib/rulesEngine/shared';
import { parseEmbeddedFte } from '@/lib/rulesEngine/loadContext';
