// eslint-disable-next-line @typescript-eslint/no-explicit-any
type SchedulingClient = any;

// ── Schedule context (loaded once per request) ───────────────────────────────

export interface ScheduleCtx {
  scheduleId: string;
  siteId: string;
  versionId: string;
  scheduleName: string;
  dateStart: string;
  dateEnd: string;
  overrideProviderIds?: string[];
}

export async function loadScheduleCtx(sb: SchedulingClient, scheduleId: string): Promise<ScheduleCtx> {
  const { data: schedule, error: schedErr } = await sb
    .from('schedules')
    .select('id, site_id, schedule_name, date_start, date_end, included_provider_ids')
    .eq('id', scheduleId)
    .maybeSingle();
  if (schedErr) throw new Error(`schedule load failed: ${schedErr.message}`);
  if (!schedule) throw new Error(`schedule ${scheduleId} not found`);

  const { data: version, error: verErr } = await sb
    .from('schedule_versions')
    .select('id, version_number')
    .eq('schedule_id', scheduleId)
    .order('version_number', { ascending: false })
    .limit(1)
    .single();
  if (verErr || !version) throw new Error('no schedule version found');

  const rawOverride = schedule.included_provider_ids;
  const overrideProviderIds: string[] | undefined =
    Array.isArray(rawOverride) && rawOverride.length > 0
      ? rawOverride.filter((x: unknown): x is string => typeof x === 'string')
      : undefined;

  return {
    scheduleId,
    siteId: schedule.site_id as string,
    versionId: version.id as string,
    scheduleName: schedule.schedule_name as string,
    dateStart: schedule.date_start as string,
    dateEnd: schedule.date_end as string,
    overrideProviderIds,
  };
}

