// ── Executors ────────────────────────────────────────────────────────────────

// Invalid model output → ToolInputError with the zod issue text; the loop
// feeds it back as an is_error tool_result so the model self-corrects.
// Nothing invalid is ever persisted (spec §7.3 safety property). The class
// lives in mutations.ts (the mutation cores throw it for version-scope
// violations); re-exported here to keep one import surface for the loop.
export { ToolInputError } from './mutations';

function zodIssueText(err: z.ZodError): string {
  return err.issues
    .map(i => `${i.path.map(String).join('.') || '(root)'}: ${i.message}`)
    .join('; ');
}

function parseWith<T>(schema: z.ZodType<T>, input: unknown): T {
  const parsed = schema.safeParse(input);
  if (!parsed.success) throw new ToolInputError(`Invalid tool input — ${zodIssueText(parsed.error)}`);
  return parsed.data;
}

// Strict tool schemas can't express free-form objects (additionalProperties
// must be false), so object-valued fields ride as JSON strings. Decode them;
// a malformed string or non-object value becomes a ToolInputError the model
// can self-correct from. Already-object values (belt-and-braces) pass through.
function decodeJsonStringFields(input: unknown, fields: string[]): unknown {
  if (typeof input !== 'object' || input === null) return input;
  const out: Record<string, unknown> = { ...(input as Record<string, unknown>) };
  for (const f of fields) {
    const v = out[f];
    if (typeof v !== 'string') continue;
    try {
      const parsed = JSON.parse(v);
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        throw new Error('not a JSON object');
      }
      out[f] = parsed;
    } catch {
      throw new ToolInputError(`${f} must be a JSON object encoded as a string`);
    }
  }
  return out;
}

export interface ToolOutcome {
  // Sent back to the model as the tool_result content (JSON-stringified).
  result: unknown;
  // One-line description for the UI change chips (mutating tools only).
  summary: string;
}

export type ToolExecutor = (
  sb: SchedulingClient,
  ctx: ScheduleCtx,
  input: unknown,
) => Promise<ToolOutcome>;

